pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Penalize opportunity destruction
    if bin_residual >= next_item_size && post_residual < next_item_size {
        score += 40.0;
    }

    // Reward exact and near-exact matching
    if post_residual == next_item_size || (post_residual >= next_item_size && post_residual - next_item_size < 10) {
        score -= 60.0;
    }

    // Last chance awareness
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Dynamic horizon awareness
    let progress = step_index as f64 / total_items as f64;
    if progress < 0.5 {
        // Early stages: prioritize large flexible spaces
        if post_residual >= 50 {
            score += 20.0;
        }
    } else {
        // Late stages: prioritize tightly closing existing bins
        if open_bins_count > 1 {
            score -= 20.0;
        }
    }

    score
}

